const texts={summary:'종합소견',management:'관리계획',followup:'추적관찰·재검 계획',questions:'의료진 검토사항 · 보호자 결과서에는 제외'};

const PHOTO_LIMIT=60;
const steps=[['exams','검사·소견'],['labs','혈액검사'],['urine','요검사'],['additional','추가 검사'],['radiograph','방사선'],['ultrasound','초음파'],['images','사진 모아보기'],['summary','종합소견·출력']];
const extraTemplates={'심장표지자':['NT-proBNP','cTnI'],'갑상선':['Total T4','Free T4','TSH'],'기초 Cortisol':['기초 Cortisol'],'ACTH 자극검사':['ACTH 전 Cortisol','ACTH 후 Cortisol'],'LDDST':['LDDST 0시간 Cortisol','LDDST 4시간 Cortisol','LDDST 8시간 Cortisol'],'감염성 검사':['심장사상충 항원','심장사상충 항체','FeLV 항원','FIV 항체']};
