 function bindLabTools(panel){updateLabTools(panel);panel.querySelectorAll('[data-lab-pick]').forEach(e=>e.onchange=()=>{const id=d.labs[+e.dataset.labPick].id;e.checked?labSelection.add(id):labSelection.delete(id);updateLabTools(panel);buttons();});panel.querySelector('[data-lab-filter]').onchange=e=>{labFilters[step]=e.target.value;render();};panel.querySelector('[data-first-review]').onclick=()=>{const i=d.labs.findIndex(r=>labTab(r)===step&&needsReview(r));if(i<0){status('확인 필요한 검사 결과가 없습니다.');return;}labFilters[step]='all';render();const el=root.querySelector('[data-row="'+i+'"]');el?.scrollIntoView({block:'center'});el?.querySelector('[data-lab=value]')?.focus();};panel.querySelector('[data-confirm-picked]').onclick=()=>{if(!edit()||busy)return;const selected=d.labs.map((r,i)=>labTab(r)===step&&labSelection.has(r.id)?i:-1).filter(i=>i>=0);if(!selected.length){status('원본과 대조한 검사를 선택해주세요.');return;}for(const i of selected)if(d.labs[i].name&&d.labs[i].value){d.labs[i].confirmed=true;labSelection.delete(d.labs[i].id);}changed();render();};panel.querySelector('[data-previous]').onclick=()=>void loadPriorList();if(prior||priorList.length||priorNext)showPrior(panel);}
 function updateLabTools(panel){const count=panel.querySelector('[data-lab-count]');if(count)count.textContent='입력 '+d.labs.filter(r=>labTab(r)===step&&r.value).length+'개 · 확인 필요 '+d.labs.filter(r=>labTab(r)===step&&needsReview(r)).length+'개';const b=panel.querySelector('[data-confirm-picked]');if(b){const n=d.labs.filter(r=>labTab(r)===step&&labSelection.has(r.id)).length,hidden=n-panel.querySelectorAll('[data-lab-pick]:checked').length;b.textContent=n?'선택 '+n+'개'+(hidden?' (숨김 '+hidden+'개 포함)':'')+' 원본 대조 완료':'검사 선택 후 대조 완료';}}
 async function loadPriorList(more=false){if(priorBusy||!item.patient_id){status(item.patient_id?'이전 검사 조회 중…':'등록 환자를 연결하면 이전 검사를 비교할 수 있습니다.');return;}const n=epoch,id=item.id;priorBusy=true;try{const r=await request('/healthcheck?'+new URLSearchParams({patientId:item.patient_id,to:d.date,...(more&&priorNext?{cursor:priorNext}:{})}));if(!live(n)||item.id!==id)return;priorList=(more?priorList:[]).concat((r.items||[]).filter(x=>x.id!==id));priorNext=r.next||'';showPrior(root.querySelector('[data-panel]'),true);status(priorList.length?'비교할 이전 검사를 선택해주세요.':priorNext?'더 불러오기를 눌러 이전 검사를 확인하세요.':'이전 검사 기록이 없습니다.');}catch(e){if(live(n))status('이전 검사 조회 실패 · '+e.message);}finally{priorBusy=false;}}
 function showPrior(panel,choose=false){const box=panel?.querySelector('[data-prior]');if(!box)return;box.innerHTML='<label>이전 검사 · 비교 전용<select data-prior-id><option value="">선택해주세요</option>'+priorList.map(x=>'<option value="'+esc(x.id)+'" '+(prior?.id===x.id?'selected':'')+'>'+esc(x.date+' · '+(x.veterinarian||'담당 미입력'))+'</option>').join('')+'</select></label>'+(priorNext?'<button data-prior-more>이전 검사 더 불러오기</button>':'')+(prior&&!choose?'<p>이전 '+esc(prior.chart.date)+' · 이번 검사값은 별도로 입력합니다.</p><div class="hc-compare-table">'+printLabs(prior.chart.labs.filter(r=>labTab(r)===step))+'</div>':'');if(priorNext)box.querySelector('[data-prior-more]').onclick=()=>void loadPriorList(true);box.querySelector('[data-prior-id]').onchange=async e=>{if(!e.target.value){prior=null;showPrior(panel,true);return;}const n=epoch,id=e.target.value,patientId=item.patient_id;try{const r=await request('/cases/'+encodeURIComponent(id)+'?view=healthcheck');if(live(n)&&item.patient_id===patientId&&r.item.patient_id===patientId&&box.isConnected&&box.querySelector('[data-prior-id]').value===id){prior={id,chart:r.item.body.healthcheckChart};showPrior(panel);}}catch(err){if(live(n))status('이전 검사 조회 실패 · '+err.message);}};}

 function labRow(r,i){const qualitative=/심장사상충|HEARTWORM|FELV|FIV/i.test(r.name),choices=['','음성','양성','판정 보류'],custom=!choices.includes(r.value);return '<article data-row="'+i+'" class="hc-lab hc-lab-compact '+(qualitative?'hc-qualitative':'')+'"><label><span class="hc-cell-label">검사명</span><input type=checkbox data-lab-pick="'+i+'" '+(labSelection.has(r.id)?'checked':'')+' aria-label="'+esc(r.name)+' 일괄 대조 대상 선택"><input aria-label="검사명" data-lab="name" value="'+esc(r.name)+'"></label>'+['value','unit','reference'].map((k,j)=>'<label><span class="hc-cell-label">'+['결과','단위','참고범위'][j]+'</span>'+(k==='unit'&&qualitative?'<span class="hc-qual-unit">'+esc(r.unit||'—')+'</span>':'')+(k==='value'&&qualitative?'<select data-qual-choice aria-label="결과 선택">'+choices.map((v,n)=>'<option value="'+v+'" '+(r.value===v?'selected':'')+'>'+(['미검사','음성','양성','판정 보류'][n])+'</option>').join('')+'<option value="__custom" '+(custom?'selected':'')+'>직접 입력</option></select>':'')+'<input '+(qualitative&&(k==='unit'||k==='value'&&!custom)?'hidden ':'')+'aria-label="'+['결과','단위','참고범위'][j]+'" data-lab="'+k+'" value="'+esc(r[k])+'"></label>').join('')+'<div class="hc-lab-check"><label class="hc-check"><input type="checkbox" data-lab="confirmed" '+(r.confirmed?'checked':'')+'>원본 대조</label><span data-range>'+esc(rangeStatus(r))+'</span></div><details><summary>상세</summary>'+(qualitative?'<label>원본 단위<input data-qual-unit value="'+esc(r.unit)+'"></label>':'')+'<label>분류<select data-lab="group">'+labGroups.map(g=>'<option '+(labGroup(r)===g?'selected':'')+'>'+g+'</option>').join('')+'</select></label><label>검사실·장비<input data-lab="source" value="'+esc(r.source)+'"></label><small>원본 검사명 '+esc(r.originalName||r.name)+' · 원본 검사일 '+esc(r.date||'직접 입력')+'</small><button data-remove-row="'+i+'">삭제</button></details></article>';}
 function renderImages(panel){
  const dedicated=imageStep(step)?step:'';if(dedicated)photoKind=dedicated;const shown=d.images.map((im,i)=>({im,i})).filter(({im})=>dedicated?im.kind===dedicated:!photoFilter||im.kind===photoFilter);
  for(const id of photoSelection)if(!d.images.some(im=>im.id===id))photoSelection.delete(id);
  panel.innerHTML=(dedicated?'<div class="hc-imaging-notes">'+examField(dedicated,exams[dedicated],d.exams[dedicated])+'</div>':'')+'<div class="hc-toolbar"><label '+(dedicated?'hidden':'')+'>사진 종류<select data-image-kind>'+Object.entries(kinds).map(([k,v])=>'<option value="'+k+'" '+(photoKind===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label class="hc-upload">사진 추가 · '+(dedicated?kinds[dedicated]+' '+shown.length+'장 · ':'')+'전체 '+d.images.length+'/'+PHOTO_LIMIT+'장<input data-image-file type="file" multiple accept="image/jpeg,image/png,image/webp"></label><label '+(dedicated?'hidden':'')+'>보기<select data-photo-filter><option value="">전체 사진</option>'+Object.entries(kinds).map(([k,v])=>'<option value="'+k+'" '+(photoFilter===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label></div><small>결과서용 축소 사진 · 원본 별도 보관 · AI 영상 판독 제외</small><div class="hc-photo-bulk"><label class="hc-check"><input type=checkbox data-photo-all>현재 목록 선택</label><span data-photo-count></span><span class="hc-bulk-actions" data-bulk-actions hidden><button data-photo-bulk="include">결과서 포함</button><button data-photo-bulk="exclude">결과서 제외</button><select data-bulk-kind aria-label="선택 사진 종류"><option value="">종류 선택</option>'+Object.entries(kinds).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select><button data-photo-bulk="kind">종류 변경</button><button data-photo-bulk="delete">선택 삭제</button></span></div><div class="hc-images">'+shown.map(({im,i})=>'<article data-photo-card="'+esc(im.id)+'"><div class="hc-photo-head"><label class="hc-check"><input type=checkbox data-photo-pick="'+esc(im.id)+'" '+(photoSelection.has(im.id)?'checked':'')+'>'+esc(kinds[im.kind])+' '+(i+1)+'</label><button data-drag="'+esc(im.id)+'" draggable="'+edit()+'" aria-label="사진 순서 끌어서 이동" title="끌어서 순서 변경">↔</button></div><button class="hc-photo-open" data-zoom="'+i+'" aria-label="사진 확대"><img loading="lazy" data-photo="'+esc(im.id)+'" alt="'+esc(kinds[im.kind])+'"></button><button data-photo-retry="'+esc(im.id)+'" hidden>사진 다시 불러오기</button><div class="hc-photo-caption">'+esc(im.caption||'설명 없음')+'</div><small>'+(im.includeInPrint!==false?'결과서 포함':'결과서 제외')+'</small><details name="hc-photo-editor" data-photo-details="'+esc(im.id)+'" '+(photoEditor===im.id?'open':'')+'><summary>설명·순서 편집</summary><label>사진 설명<textarea data-caption="'+i+'" maxlength="160" placeholder="의료진이 확인한 소견">'+esc(im.caption)+'</textarea></label><label class="hc-check"><input type=checkbox data-print-image="'+i+'" '+(im.includeInPrint!==false?'checked':'')+'>결과서에 포함</label><div class="hc-photo-actions"><button data-shift="'+i+'" data-dir="-1" '+(i===0?'disabled':'')+'>앞으로</button><button data-shift="'+i+'" data-dir="1" '+(i===d.images.length-1?'disabled':'')+'>뒤로</button><button data-remove-image="'+i+'">삭제</button></div></details></article>').join('')+'</div>';
  const update=()=>{panel.querySelector('[data-bulk-actions]').hidden=!photoSelection.size;panel.querySelector('[data-photo-count]').textContent='선택 '+photoSelection.size+'장'+(photoSelection.size>shown.filter(({im})=>photoSelection.has(im.id)).length?' · 숨김 '+(photoSelection.size-shown.filter(({im})=>photoSelection.has(im.id)).length)+'장 포함':'');const all=panel.querySelector('[data-photo-all]'),n=shown.filter(({im})=>photoSelection.has(im.id)).length;all.checked=!!shown.length&&n===shown.length;all.indeterminate=n>0&&n<shown.length;buttons();};
  panel.querySelector('[data-image-kind]').onchange=e=>photoKind=e.target.value;
  panel.querySelector('[data-image-file]').onchange=e=>void addImages([...e.target.files],panel.querySelector('[data-image-kind]').value);
  panel.querySelector('[data-photo-filter]').onchange=e=>{photoFilter=e.target.value;render();};
  panel.querySelectorAll('[data-photo-pick]').forEach(e=>e.onchange=()=>{e.checked?photoSelection.add(e.dataset.photoPick):photoSelection.delete(e.dataset.photoPick);update();});
  panel.querySelector('[data-photo-all]').onchange=e=>{for(const {im} of shown)e.target.checked?photoSelection.add(im.id):photoSelection.delete(im.id);panel.querySelectorAll('[data-photo-pick]').forEach(x=>x.checked=photoSelection.has(x.dataset.photoPick));update();};
  panel.querySelectorAll('[data-photo-bulk]').forEach(b=>b.onclick=()=>{if(!edit()||busy||pending||!photoSelection.size)return;const op=b.dataset.photoBulk,kind=panel.querySelector('[data-bulk-kind]').value;if(op==='kind'&&!kind){status('변경할 사진 종류를 선택해주세요.');return;}if(op==='delete'){for(const id of photoSelection)imageCache.delete(id);d.images=d.images.filter(im=>!photoSelection.has(im.id));photoSelection.clear();}else for(const im of d.images)if(photoSelection.has(im.id)){if(op==='kind')im.kind=kind;else im.includeInPrint=op==='include';}changed(op==='delete'||op==='kind');render();});
  panel.querySelectorAll('[data-photo-details]').forEach(e=>e.ontoggle=()=>{if(e.open){photoEditor=e.dataset.photoDetails;panel.querySelectorAll('[data-photo-details]').forEach(x=>{if(x!==e)x.open=false;});}else if(photoEditor===e.dataset.photoDetails)photoEditor='';});
  panel.querySelectorAll('[data-caption]').forEach(e=>e.oninput=()=>{d.images[+e.dataset.caption].caption=e.value;e.closest('article').querySelector('.hc-photo-caption').textContent=e.value||'설명 없음';changed();});
  panel.querySelectorAll('[data-print-image]').forEach(e=>e.onchange=()=>{d.images[+e.dataset.printImage].includeInPrint=e.checked;e.closest('article').querySelector(':scope>small').textContent=e.checked?'결과서 포함':'결과서 제외';changed(false);});
  panel.querySelectorAll('[data-remove-image]').forEach(b=>b.onclick=()=>{photoSelection.delete(d.images[+b.dataset.removeImage].id);imageCache.delete(d.images[+b.dataset.removeImage].id);d.images.splice(+b.dataset.removeImage,1);changed();render();});
  const move=(from,to)=>{if(!edit()||busy||pending||from<0||to<0||to>=d.images.length||from===to)return;const [im]=d.images.splice(from,1);d.images.splice(to,0,im);changed(false);render();};
  panel.querySelectorAll('[data-shift]').forEach(b=>b.onclick=()=>move(+b.dataset.shift,+b.dataset.shift+(+b.dataset.dir)));
  panel.querySelectorAll('[data-drag]').forEach(b=>b.ondragstart=e=>{if(!edit()||busy||pending){e.preventDefault();return;}e.dataTransfer.setData('text/carestep-photo',b.dataset.drag);e.dataTransfer.effectAllowed='move';});
  panel.querySelectorAll('[data-photo-card]').forEach(card=>{card.ondragover=e=>{if(edit()&&!busy&&!pending&&Array.from(e.dataTransfer.types).includes('text/carestep-photo'))e.preventDefault();};card.ondrop=e=>{e.preventDefault();move(d.images.findIndex(im=>im.id===e.dataTransfer.getData('text/carestep-photo')),d.images.findIndex(im=>im.id===card.dataset.photoCard));};});
  panel.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=async()=>{try{const n=epoch,url=await imageURL(d.images[+b.dataset.zoom]);if(!live(n)||!b.isConnected)return;const modal=document.createElement('dialog');modal.className='hc-photo-dialog';modal.innerHTML='<button>닫기</button><img alt="검사 사진 확대">';modal.querySelector('img').src=url;modal.querySelector('button').onclick=()=>modal.close();modal.onclose=()=>modal.remove();root.append(modal);modal.showModal();}catch(e){status('사진 조회 실패 · '+e.message);}});
  const n=epoch,queue=[],queued=new Set();let active=0;
  const pump=()=>{while(active<2&&queue.length&&live(n)&&panel.isConnected){const el=queue.shift(),im=d.images.find(x=>x.id===el.dataset.photo),retry=el.closest('article').querySelector('[data-photo-retry]');active++;imageURL(im).then(url=>{if(live(n)&&el.isConnected){el.src=url;retry.hidden=true;}}).catch(()=>{if(live(n)&&el.isConnected){el.alt='사진 불러오기 실패';retry.hidden=false;}}).finally(()=>{active--;pump();});}};
  const enqueue=el=>{if(!queued.has(el)){queued.add(el);queue.push(el);pump();}};
  panel.querySelectorAll('[data-photo-retry]').forEach(b=>b.onclick=()=>{const el=b.closest('article').querySelector('[data-photo]');b.hidden=true;queued.delete(el);enqueue(el);});
  if('IntersectionObserver' in g){photoObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){photoObserver.unobserve(entry.target);enqueue(entry.target);}},{rootMargin:'180px'});panel.querySelectorAll('[data-photo]').forEach(el=>photoObserver.observe(el));}else panel.querySelectorAll('[data-photo]').forEach(enqueue);
  update();
 }
 async function imageURL(im){if(im.dataUrl)return im.dataUrl;if(imageCache.has(im.id))return imageCache.get(im.id);const n=epoch,key=im.id,task=request('/cases/'+item.id+'/healthcheck-images?id='+encodeURIComponent(key)).then(r=>{if(!live(n))throw Error('환자가 변경됐습니다.');imageCache.set(key,r.dataUrl);return r.dataUrl;}).catch(e=>{imageCache.delete(key);throw e;});imageCache.set(key,task);return task;}
 async function addImages(files,kind){if(!files.length||busy||!edit())return;if(d.images.length+files.length>PHOTO_LIMIT){status('사진은 총 '+PHOTO_LIMIT+'장까지 첨부할 수 있습니다. 현재 '+d.images.length+'장입니다.');return;}const n=epoch;busy=true;buttons();let added=0,failed=[];try{for(const file of files){if(!live(n))break;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw Error('15MB 이하 JPG·PNG·WebP 필요');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.85,data=canvas.toDataURL('image/jpeg',quality);while(data.length>120000&&quality>.25){quality-=.1;data=canvas.toDataURL('image/jpeg',quality);}if(data.length>120000)throw Error('파일 크기를 줄여주세요');if(live(n)){d.images.push({id:uid(),kind,caption:'',dataUrl:data,includeInPrint:true});added++;changed();status('사진 준비 중 · '+added+'/'+files.length+'장');}}catch(e){failed.push(file.name+' · '+e.message);}}if(live(n))error=added+'장 첨부 완료 · 저장 전'+(failed.length?' / 첨부 실패: '+failed.join(', '):'');}finally{busy=false;if(live(n))render();}}
 function renderSummary(panel){panel.innerHTML='<label class="hc-check"><input type="checkbox" data-ai-consent>입력한 검사·소견을 연결된 AI로 전송합니다. 식별정보를 자유기록에 넣지 않았습니다.</label><button data-action="ai">AI 종합소견·관리계획 초안</button>'+(proposal?'<section class="hc-proposal"><h3>AI 제안 · 반영할 항목만 선택</h3>'+Object.entries(texts).map(([k,l])=>'<article><label class="hc-check"><input type=checkbox data-ai-pick="'+k+'" '+(!d[k]?'checked':'')+'>'+l+'</label><div class="hc-ai-compare"><div><b>현재 내용</b><p data-ai-current="'+k+'">'+esc(d[k]||'미입력')+'</p></div><div><b>AI 제안</b><p>'+esc(proposal[k])+'</p></div></div></article>').join('')+'<button data-action="apply-ai">선택한 내용 반영</button><button data-action="discard-ai">제안 닫기</button></section>':'')+(undoAI?'<button data-action="undo-ai">방금 AI 반영 되돌리기</button>':'')+'<div class="hc-summary-grid">'+Object.entries(texts).filter(([k])=>k!=='questions').map(([k,l])=>'<label>'+l+'<textarea data-prose="'+k+'" rows="5">'+esc(d[k])+'</textarea></label>').join('')+'</div><details class="hc-review-notes"><summary>의료진 검토사항 · '+(d.questions?'내용 있음':'입력 없음')+' · 결과서 제외</summary><textarea data-prose="questions" aria-label="의료진 검토사항" rows="4">'+esc(d.questions)+'</textarea></details>'+'<div class="hc-summary-vet">'+field('veterinarian','담당 수의사')+'</div><label class="hc-check"><input type="checkbox" data-review '+(d.reviewed?'checked':'')+'>검사·참고범위·종합소견·관리계획을 검토했습니다.</label><div class="hc-summary-actions"><button data-action="complete" class="pt-primary">검토 완료·저장</button><button data-action="print">미리보기·인쇄/PDF</button></div>';panel.querySelectorAll('[data-prose]').forEach(e=>e.oninput=()=>{const key=e.dataset.prose;d[key]=e.value;if(key==='questions')panel.querySelector('.hc-review-notes summary').textContent='의료진 검토사항 · '+(e.value?'내용 있음':'입력 없음')+' · 결과서 제외';const pick=panel.querySelector('[data-ai-pick="'+key+'"]'),current=panel.querySelector('[data-ai-current="'+key+'"]');if(pick)pick.checked=false;if(current)current.textContent=e.value||'미입력';undoAI=null;changed(false);});panel.querySelector('[data-review]').onchange=e=>{d.reviewed=e.target.checked;if(!d.reviewed&&d.clinicalStatus==='complete')d.clinicalStatus='amended';dirty=true;root.querySelector('[data-save-state]').textContent='저장 전 변경 있음';};}
 async function generate(){if(busy||!edit())return;if(!root.querySelector('[data-ai-consent]')?.checked){status('AI 전송 여부를 확인해주세요.');return;}if(d.labs.some(r=>r.value&&!r.confirmed)){status('검사값·참고범위를 먼저 대조해주세요.');return;}if(d.images.some(im=>im.dataUrl&&!im.imageRevision)){status('새로 첨부한 사진을 먼저 저장한 뒤 AI 초안을 생성해주세요.');return;}const n=epoch;busy=true;aiBusy=true;render();status('종합소견 작성 중…');try{const chart=copy(d);chart.images=chart.images.map(({dataUrl,...im})=>im);const r=await request('/healthcheck-summary',{method:'POST',body:{species:item.body.species,chart,consent:true,recordId:item.id}});if(live(n)){proposal=r;error='AI 제안을 확인하고 반영해주세요.';}}catch(e){if(live(n))error=e.message;}finally{busy=false;aiBusy=false;if(live(n))render();}}
